`timescale 1ns/1ps

module tb_bg_rom;

    reg bg_select;
    reg [9:0] edge_addr;
    reg [2:0] i_ls;
    reg [9:0] zc;

    wire edge_valid;
    wire [5:0] row_index;
    wire [6:0] col_index;
    wire [8:0] shift_value;

    integer errors = 0;
    integer checks = 0;

    bg_rom DUT (
        .bg_select(bg_select),
        .edge_addr(edge_addr),
        .i_ls(i_ls),
        .zc(zc),
        .edge_valid(edge_valid),
        .row_index(row_index),
        .col_index(col_index),
        .shift_value(shift_value)
    );

    task check_edge;
        input bg;
        input [9:0] addr;
        input [2:0] ils;
        input [9:0] z;
        input [5:0] exp_row;
        input [6:0] exp_col;
        input [8:0] exp_shift;
        begin
            bg_select = bg;
            edge_addr = addr;
            i_ls = ils;
            zc = z;
            #1;
            checks = checks + 1;
            if (edge_valid !== 1'b1 ||
                row_index !== exp_row ||
                col_index !== exp_col ||
                shift_value !== exp_shift) begin
                errors = errors + 1;
                $display(
                    "ERROR addr=%0d BG=%0d iLS=%0d Zc=%0d got valid=%b row=%0d col=%0d shift=%0d expected row=%0d col=%0d shift=%0d",
                    addr, bg, ils, z, edge_valid,
                    row_index, col_index, shift_value,
                    exp_row, exp_col, exp_shift
                );
            end
        end
    endtask

    task check_invalid;
        input bg;
        input [9:0] addr;
        input [9:0] z;
        begin
            bg_select = bg;
            edge_addr = addr;
            i_ls = 3'd0;
            zc = z;
            #1;
            checks = checks + 1;
            if (edge_valid !== 1'b0) begin
                errors = errors + 1;
                $display("ERROR: invalid address accepted: BG=%0d addr=%0d", bg, addr);
            end
        end
    endtask

    initial begin
        bg_select = 0;
        edge_addr = 0;
        i_ls = 0;
        zc = 384;

        $display("======================================");
        $display("5G NR BG ROM AUTOMATED TEST");
        $display("======================================");

        check_edge(1'b0, 10'd0, 3'd0, 10'd384, 6'd0, 7'd0, 9'd250);
        check_edge(1'b0, 10'd0, 3'd0, 10'd8, 6'd0, 7'd0, 9'd2);
        check_edge(1'b0, 10'd0, 3'd1, 10'd384, 6'd0, 7'd0, 9'd307);
